async page => {
  const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/l9sAAAAASUVORK5CYII=', 'base64');
  const image = {name:'cover.png', mimeType:'image/png', buffer:png};
  let uploads = 0, fail = true, wait = false, release;
  const saves = [], errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.route('**/cover-fixture.png', r => r.fulfill({body:png,contentType:'image/png'}));
  await page.route('**/merchant/workspace/image/upload', async route => {
    uploads++;
    if (route.request().headers().authorization !== 'cover-fixture-only') throw Error('未使用商家令牌上传');
    if (!route.request().headers()['content-type'].includes('multipart/form-data; boundary=')) throw Error('未正确使用multipart上传');
    if (wait) await new Promise(resolve => {release=resolve;});
    return route.fulfill({json:fail ? {code:1001,message:'模拟上传失败，请重试'} : {code:1000,data:'/cover-fixture.png'}});
  });
  await page.route('**/merchant/workspace/*/save', async route => {
    saves.push(route.request().postDataJSON());
    await route.fulfill({json:{code:1000,data:7}});
  });
  const input = () => page.locator('.merchant-image-upload input[type=file]');
  if (await page.getByRole('textbox',{name:'封面地址',exact:true}).count()) throw Error('仍有手填地址');
  await input().setInputFiles({name:'text.txt',mimeType:'text/plain',buffer:Buffer.from('not-image')});
  await page.getByText('请选择JPG、PNG或GIF图片',{exact:true}).waitFor();
  if (uploads) throw Error('非法类型仍然发起上传');
  await input().setInputFiles(image);
  await page.getByText('模拟上传失败，请重试',{exact:true}).first().waitFor();
  fail=false;
  await input().setInputFiles(image);
  await page.getByRole('button',{name:'更换图片',exact:true}).waitFor();
  await page.locator('.merchant-image-upload .preview img').waitFor();
  fail=true;
  await input().setInputFiles(image);
  await page.getByText('模拟上传失败，请重试',{exact:true}).first().waitFor();
  if (await page.locator('.merchant-image-upload .preview img').getAttribute('src') !== '/cover-fixture.png') throw Error('失败丢失原图');
  await page.getByRole('button',{name:'移除图片',exact:true}).click();
  await page.getByRole('button',{name:'上传图片',exact:true}).waitFor();
  await page.getByRole('textbox',{name:'门店名称*',exact:true}).fill('测试门店');
  await page.getByRole('textbox',{name:'联系电话*',exact:true}).fill('13900000000');
  await page.getByRole('textbox',{name:'详细地址*',exact:true}).fill('测试地址');
  await page.getByRole('combobox',{name:'门店类型*',exact:true}).locator('..').locator('..').click();
  await page.getByRole('option',{name:'直营店',exact:true}).click();
  fail=false; wait=true;
  await input().setInputFiles(image);
  await page.waitForTimeout(200);
  await page.getByRole('button',{name:'保存',exact:true}).click();
  await page.getByText('图片正在上传，请上传完成后再保存',{exact:true}).waitFor();
  if (saves.length) throw Error('上传期间保存了资料');
  release(); wait=false;
  await page.getByRole('button',{name:'更换图片',exact:true}).waitFor();
  await page.screenshot({path:'output/playwright/store-cover-upload-20261027.png',fullPage:true});
  await page.getByRole('button',{name:'保存',exact:true}).click();
  await page.getByRole('dialog').waitFor({state:'hidden'});
  if (saves[0]?.cover !== '/cover-fixture.png') throw Error('门店未保存上传地址');
  await page.goto('http://127.0.0.1:9001/merchant/coupons');
  await page.getByRole('button',{name:'新增',exact:true}).click();
  await page.getByRole('group',{name:'优惠券封面',exact:true}).waitFor();
  await input().setInputFiles(image);
  await page.getByRole('button',{name:'更换图片',exact:true}).waitFor();
  await page.getByRole('textbox',{name:'券名称*',exact:true}).fill('测试券');
  await page.getByRole('button',{name:'保存',exact:true}).click();
  await page.getByRole('dialog').waitFor({state:'hidden'});
  if (saves[1]?.cover !== '/cover-fixture.png') throw Error('优惠券未保存上传地址');
  if (errors.length) throw Error(errors.join(';'));
  return {passed:true,uploads,simulatedSaves:saves.length,pageErrors:errors.length};
}
